\set ON_ERROR_STOP on
begin;
create temporary table followup_results(name text primary key);
grant all on followup_results to anon,authenticated,service_role;
create function pg_temp.assert(ok boolean,name text) returns void language plpgsql as $$ begin
 if ok is distinct from true then raise exception 'FAIL: %',name;end if;insert into followup_results values(name);
end $$;
create function pg_temp.denied(sql_text text,name text) returns void language plpgsql as $$ declare rejected boolean:=false;begin
 begin execute sql_text;exception when insufficient_privilege or sqlstate 'P0001' or check_violation then rejected:=true;end;
 perform pg_temp.assert(rejected,name);
end $$;
create function pg_temp.id(n integer) returns uuid language sql immutable as $$ select ('b0000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid $$;
create function pg_temp.login(n integer,aal text default 'aal1') returns void language plpgsql as $$ begin
 perform set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'role','authenticated','aal',aal,'session_id',('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid)::text,true);
end $$;
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data) select pg_temp.id(n),'followup'||n||'@example.test',now(),'{"icarus_server_created":true}',jsonb_build_object('full_name','DEMONSTRAÇÃO followup '||n) from generate_series(1,5)n;
set constraints all immediate;
insert into auth.sessions(id,user_id,created_at,updated_at,aal) select ('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,pg_temp.id(n),now(),now(),case when n>=3 then 'aal2'::auth.aal_level else 'aal1'::auth.aal_level end from generate_series(1,5)n;
update public.profiles set role=case id when pg_temp.id(3) then 'admin' when pg_temp.id(4) then 'support' when pg_temp.id(5) then 'moderator' else 'member' end,demo=true where id in (select pg_temp.id(n) from generate_series(1,5)n);
insert into public.plans(id,name,slug,price_cents,access_months,active) values(pg_temp.id(50),'DEMONSTRAÇÃO followup','demo-followup',10000,12,true);
insert into public.subscriptions(user_id,plan_id,starts_at,ends_at,source) select pg_temp.id(1),pg_temp.id(50),now()-n*interval '1 day',now()+interval '1 month','courtesy' from generate_series(1,21)n;
insert into public.courses(id,slug,title,status,access_mode,certificate_enabled,signer_name,signer_title) values(pg_temp.id(100),'followup-course','DEMONSTRAÇÃO followup curso','published','subscribers',true,'DEMONSTRAÇÃO responsável','Instrutor'),(pg_temp.id(200),'followup-other','SEGREDO_TERCEIRO_CURSO','published','members',false,'',''),(pg_temp.id(300),'followup-empty','DEMONSTRAÇÃO vazio','published','members',true,'DEMONSTRAÇÃO responsável','Instrutor');
insert into public.modules(id,course_id,slug,title,status) values(pg_temp.id(101),pg_temp.id(100),'modulo','DEMONSTRAÇÃO módulo','published'),(pg_temp.id(201),pg_temp.id(200),'outro','Outro módulo','published');
insert into public.sections(id,module_id,title,status) values(pg_temp.id(102),pg_temp.id(101),'DEMONSTRAÇÃO seção','published'),(pg_temp.id(202),pg_temp.id(201),'Outra seção','published');
insert into public.lessons(id,section_id,slug,title,duration_seconds,status) values(pg_temp.id(103),pg_temp.id(102),'aula','DEMONSTRAÇÃO aula',60,'published'),(pg_temp.id(203),pg_temp.id(202),'outra','Outra aula',60,'published');
insert into public.lesson_progress(user_id,lesson_id,position_seconds,completed_at) values(pg_temp.id(2),pg_temp.id(203),60,now());
insert into public.orders(user_id,plan_id,attempt_key,amount_cents,access_months,method,installments,buyer_data,receipt_hash) select pg_temp.id(1),pg_temp.id(50),'followup-order-fixture-'||n,10000,12,'PIX',1,'{"email":"followup1@example.test","document":"DEMO_NO_REAL_DOCUMENT"}',repeat('a',64) from generate_series(1,21)n;
insert into public.orders(user_id,plan_id,attempt_key,amount_cents,access_months,method,installments,buyer_data,receipt_hash) values(pg_temp.id(2),pg_temp.id(50),'followup-other-fixture-01',10000,12,'PIX',1,'{"email":"SEGREDO_TERCEIRO_PEDIDO"}',repeat('b',64));
select pg_temp.login(1);
set local role authenticated;
select public.app_create_ticket('DEMONSTRAÇÃO urgente','urgent','Mensagem de teste') as ticket \gset
select pg_temp.assert(public.app_ticket((:'ticket'::jsonb->>'id')::uuid)->>'priority'='urgent','urgent ticket accepted');
select pg_temp.denied(format('select public.app_ticket_reply(%L,%L,%L)',:'ticket'::jsonb->>'id','Fechar indevidamente','resolved'),'member cannot resolve');
select pg_temp.denied(format('select public.app_ticket_reply(%L,%L,%L)',:'ticket'::jsonb->>'id','Alterar fila','waiting_member'),'member cannot set staff status');
select pg_temp.assert(not (public.app_course('followup-course')->'course'->>'can_issue')::boolean,'incomplete certificate not eligible');
select pg_temp.assert(public.app_progress(pg_temp.id(103),10,false)->>'certificate_code' is null,'playback does not issue');
reset role;
select pg_temp.login(2);
set local role authenticated;
select pg_temp.denied(format('select public.app_ticket_reply(%L,%L,%L)',:'ticket'::jsonb->>'id','Outra pessoa','open'),'B cannot reopen A ticket');
select pg_temp.denied(format('select public.app_admin_member_detail(%L)',pg_temp.id(1)),'member cannot read member dossier');
reset role;
select pg_temp.login(4,'aal2');
set local role authenticated;
select pg_temp.assert(public.app_ticket_reply((:'ticket'::jsonb->>'id')::uuid,'Em atendimento','in_progress')->>'status'='in_progress','support in progress');
select pg_temp.assert(public.app_ticket_reply((:'ticket'::jsonb->>'id')::uuid,'Aguardando retorno',null)->>'status'='waiting_member','support default waiting member');
select pg_temp.assert(public.app_ticket_reply((:'ticket'::jsonb->>'id')::uuid,'Resolvido','resolved')->>'status'='resolved','support resolves');
select pg_temp.denied(format('select public.app_ticket_reply(%L,%L,%L)',:'ticket'::jsonb->>'id','Alias antigo','closed'),'old closed mutation rejected');
select pg_temp.denied(format('select public.app_ticket_reply(%L,%L,%L)',:'ticket'::jsonb->>'id','Alias antigo','pending'),'old pending mutation rejected');
select pg_temp.denied(format('select public.app_admin_member_detail(%L)',pg_temp.id(1)),'support cannot read admin member dossier');
reset role;
select pg_temp.login(5,'aal2');
set local role authenticated;
select pg_temp.denied(format('select public.app_ticket(%L)',:'ticket'::jsonb->>'id'),'moderator cannot read support ticket');
reset role;
select pg_temp.login(1);
set local role authenticated;
select pg_temp.assert(public.app_ticket_reply((:'ticket'::jsonb->>'id')::uuid,'Reabrir','open')->>'status'='open','owner reopens');
select pg_temp.assert(public.app_issue_certificate(pg_temp.id(300))->>'reason' like '%currículo obrigatório%','empty curriculum explicit reason');
reset role;
-- Preserve a saved completion; reads must report eligibility without issuing.
update public.lesson_progress set completed_at=now() where user_id=pg_temp.id(1) and lesson_id=pg_temp.id(103);
select pg_temp.login(1);
set local role authenticated;
select pg_temp.assert((public.app_course('followup-course')->'course'->>'can_issue')::boolean,'completed current entitlement eligible');
select pg_temp.assert((select (x->>'can_issue')::boolean from jsonb_array_elements(public.app_certificates()->'courses') x where x->>'id'=pg_temp.id(100)::text),'certificate list exposes server eligibility');
reset role;
select pg_temp.assert(not exists(select 1 from public.certificates where user_id=pg_temp.id(1)),'course and certificates reads never issue');
select pg_temp.login(1);
set local role authenticated;
select pg_temp.assert(public.app_issue_certificate(pg_temp.id(100))->>'certificate_code' is not null,'explicit issuance uses shared predicate');
select pg_temp.assert(not (public.app_course('followup-course')->'course'->>'can_issue')::boolean,'issued current version cannot issue again');
select pg_temp.assert(public.app_course('followup-course')->'course'->>'certificate_reason'='Certificado já emitido.','issued reason exact');
select pg_temp.assert(public.app_progress(pg_temp.id(103),60,true)->>'certificate_code' is not null,'repeat completion retrieves same emission');
reset role;
select pg_temp.assert((select count(*)=1 from public.certificates where user_id=pg_temp.id(1)),'one issuance after explicit and progress');
update public.subscriptions set revoked_at=now() where user_id=pg_temp.id(1);
select pg_temp.login(1);
set local role authenticated;
select pg_temp.assert(public.app_course('followup-course')->'course'->>'certificate_reason' like '%plano ou sua vigência%','revoked entitlement reason from server');
reset role;
insert into public.tickets(user_id,subject,priority) select pg_temp.id(1),'DEMONSTRAÇÃO relacionado '||n,'normal' from generate_series(1,21)n;
insert into public.tickets(user_id,subject,priority) values(pg_temp.id(2),'SEGREDO_TERCEIRO_TICKET','urgent');
insert into auth.mfa_factors(id,user_id,friendly_name,factor_type,status,created_at,updated_at) values('b0000000-0000-4000-8000-999999999999',pg_temp.id(3),'DEMONSTRAÇÃO admin MFA','totp','verified',now(),now());
select pg_temp.login(3);
set local role authenticated;
select pg_temp.denied(format('select public.app_admin_member_detail(%L)',pg_temp.id(1)),'AAL1 admin dossier denied');
reset role;
select pg_temp.login(3,'aal2');
set local role authenticated;
select public.app_admin_member_detail(pg_temp.id(1)) as detail \gset
select pg_temp.assert(:'detail'::jsonb->'profile'->>'id'=pg_temp.id(1)::text,'dossier exact profile');
select pg_temp.assert(jsonb_array_length(:'detail'::jsonb->'subscriptions'->'items')=20 and (:'detail'::jsonb->'subscriptions'->>'total')::integer=21,'subscriptions limit20 real total21');
select pg_temp.assert(jsonb_array_length(:'detail'::jsonb->'orders'->'items')=20 and (:'detail'::jsonb->'orders'->>'total')::integer=21,'orders limit20 real total21');
select pg_temp.assert(jsonb_array_length(:'detail'::jsonb->'tickets'->'items')=20 and (:'detail'::jsonb->'tickets'->>'total')::integer=22,'tickets limit20 real total22');
select pg_temp.assert(jsonb_array_length(:'detail'::jsonb->'courses'->'items')=1 and (:'detail'::jsonb->'courses'->>'total')::integer=1,'related progress courses only');
select pg_temp.assert(:'detail'::jsonb->'courses'->'items'->0->>'progress_percent'='100','dossier contains real course progress');
select pg_temp.assert(:'detail' not like '%SEGREDO_TERCEIRO%','dossier excludes other member data');
select pg_temp.assert(:'detail' not like '%receipt_hash%' and :'detail' not like '%buyer_data%' and :'detail' not like '%attempt_key%','dossier excludes payment secrets and buyer document');
select pg_temp.denied(format('select public.app_admin_member_detail(%L)',pg_temp.id(999)),'missing member safe failure');
reset role;
select pg_temp.assert(not has_function_privilege('anon','public.app_admin_member_detail(uuid)','EXECUTE'),'anonymous dossier grant closed');
select count(*) as followup_assertions from followup_results;
rollback;
